import hotel.web.HttpApi;
import io.javalin.Javalin;
import javax.sql.DataSource;

/** Puts the inn's pieces together and runs the HTTP server. */
public final class Hotel {

    private final Javalin server;

    private static final String ARCHIVE_ADDRESS = "arquivo@pousadamarealta.com.br";
    private static final String TEST_ADDRESS = "testes@pousadamarealta.com.br";

    public Hotel(DataSource dataSource) {
        this(dataSource, false);
    }

    public Hotel(DataSource dataSource, boolean testMode) {
        Rooms rooms = new Rooms(dataSource);
        ReservationStore store = new ReservationStore(dataSource);
        SentMessages sentMessages = new SentMessages(dataSource);
        ReservationService reservations =
                new ReservationService(rooms, store, new PriceCalculator(), messageSender(sentMessages, testMode));
        HttpApi api = new HttpApi(
                rooms, reservations, sentMessages, new OccupancyReport(rooms, store), new RevenueReport(store));
        this.server = api.server();
    }

    /** The rules about sending a message, wrapped around the real sender; each installation picks its own here. */
    private static MessageSender messageSender(SentMessages sentMessages, boolean testMode) {
        MessageSender sender = new EmailSender(sentMessages);
        if (testMode) {
            return new ValidAddressOnly(new RedirectToTestAddress(sender, TEST_ADDRESS), sentMessages);
        }
        return new ArchiveCopy(new ValidAddressOnly(sender, sentMessages), ARCHIVE_ADDRESS);
    }

    /** Starts listening; port 0 picks a free port. Returns the port in use. */
    public int start(int port) {
        server.start(port);
        return server.port();
    }

    public void stop() {
        server.stop();
    }

